From 0ca5c7d09e79a1c74452ad83dde77693884061f8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:00:27 +0100
Subject: [PATCH] desktoppackage: make recording a mouse action trigger clearer

Recording showed only "Input Here", ignored used triggers silently and
could not be cancelled. A message now explains what to do and warns of
used triggers, and Escape or moving focus away cancels the recording.

BUG: 404600
---
 .../ConfigurationContainmentActions.qml       | 54 +++++++++++++-----
 .../configuration/MouseEventInputButton.qml   | 57 +++++++++++--------
 2 files changed, 71 insertions(+), 40 deletions(-)

diff --git a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
index 5cac407e79..d8fb934ad4 100644
--- a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
+++ b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
@@ -9,6 +9,7 @@ import QtQuick.Controls as QQC2
 import QtQuick.Layouts

 import org.kde.kcmutils as KCM
+import org.kde.kirigami as Kirigami

 KCM.SimpleKCM {
     id: root
@@ -31,6 +32,32 @@ KCM.SimpleKCM {
         "MetaModifier": i18ndc("plasma_shell_org.kde.plasma.desktop", "@label for shortcuts", "Meta")
     }

+    property MouseEventInputButton recordingButton: null
+
+    function prettyEventString(eventString) {
+        var splitAction = eventString.split(';');
+
+        var button = splitAction[0];
+        var modifiers = (splitAction[1] || "").split('|').filter(function (item) {
+            return item !== "NoModifier";
+        });
+
+        var parts = modifiers;
+        modifiers.push(button);
+
+        return parts.map(function (item) {
+            return root.prettyStrings[item] || item;
+        }).join(i18ndc("plasma_shell_org.kde.plasma.desktop", "Concatenation sign for shortcuts, e.g. Ctrl+Shift", "+"));
+    }
+
+    function updateRecordingButton(button) {
+        if (button.checked) {
+            recordingButton = button;
+        } else if (recordingButton === button) {
+            recordingButton = null;
+        }
+    }
+
     function saveConfig() {
         configDialog.currentContainmentActionsModel.save();
     }
@@ -42,6 +69,15 @@ KCM.SimpleKCM {
         }
     }

+    footer: Kirigami.InlineMessage {
+        position: Kirigami.InlineMessage.Position.Footer
+        visible: root.recordingButton !== null
+        type: root.recordingButton?.usedTrigger ? Kirigami.MessageType.Warning : Kirigami.MessageType.Information
+        text: root.recordingButton?.usedTrigger
+            ? i18ndc("plasma_shell_org.kde.plasma.desktop", "@info %1 is a mouse trigger, e.g. Ctrl+Right-Button", "%1 is already used by another action. Use a different mouse button or modifier key, or press Escape to cancel.", root.prettyEventString(root.recordingButton.usedTrigger))
+            : i18ndc("plasma_shell_org.kde.plasma.desktop", "@info", "Click the highlighted button with the mouse button you want to use, or scroll over it. Hold Shift, Ctrl, Alt or Meta at the same time to combine them with it. Press Escape to cancel.")
+    }
+
     GridLayout {
         id: mainColumn
         flow: GridLayout.TopToBottom
@@ -56,21 +92,8 @@ KCM.SimpleKCM {
                 Layout.row: index
                 Layout.fillWidth: true
                 Layout.minimumWidth: implicitWidth
-                defaultText: {
-                    var splitAction = model.action.split(';');
-
-                    var button = splitAction[0];
-                    var modifiers = (splitAction[1] || "").split('|').filter(function (item) {
-                        return item !== "NoModifier";
-                    });
-
-                    var parts = modifiers;
-                    modifiers.push(button);
-
-                    return parts.map(function (item) {
-                        return root.prettyStrings[item] || item;
-                    }).join(i18ndc("plasma_shell_org.kde.plasma.desktop", "Concatenation sign for shortcuts, e.g. Ctrl+Shift", "+"));
-                }
+                defaultText: root.prettyEventString(model.action)
+                onCheckedChanged: root.updateRecordingButton(this)
                 eventString: model.action
                 onEventStringChanged: {
                     configDialog.currentContainmentActionsModel.update(index, eventString, model.pluginName);
@@ -138,6 +161,7 @@ KCM.SimpleKCM {
         MouseEventInputButton {
             defaultText: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button", "Add Action");
             icon.name: checked ? "input-mouse-symbolic" : "list-add"
+            onCheckedChanged: root.updateRecordingButton(this)
             onEventStringChanged: {
                 configDialog.currentContainmentActionsModel.append(eventString, "org.kde.contextmenu");
             }
diff --git a/desktoppackage/contents/configuration/MouseEventInputButton.qml b/desktoppackage/contents/configuration/MouseEventInputButton.qml
index aeb4f83071..c156ad6cb8 100644
--- a/desktoppackage/contents/configuration/MouseEventInputButton.qml
+++ b/desktoppackage/contents/configuration/MouseEventInputButton.qml
@@ -11,47 +11,54 @@ import QtQuick.Controls as QQC2
 QQC2.Button {
     id: mouseInputButton
     property string defaultText: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button inactive state for button recording mouse input" ,"Add Action")
-    text: defaultText
+    text: checked ? i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button active state for button recording mouse input", "Click or Scroll Here") : defaultText
     checkable: true
     property string eventString
+    // The last trigger entered while recording that another action already uses
+    property string usedTrigger

     onCheckedChanged: {
+        usedTrigger = "";
         if (checked) {
-            text = i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button active state for button recording mouse input", "Input Here");
-            mouseInputArea.enabled = true;
+            forceActiveFocus();
         }
     }
+    onActiveFocusChanged: {
+        if (!activeFocus) {
+            checked = false;
+        }
+    }
+    Keys.onEscapePressed: event => {
+        event.accepted = checked;
+        checked = false;
+    }
+
+    function setEventString(newEventString) {
+        if (mouseInputButton.eventString === newEventString || !configDialog.currentContainmentActionsModel.isTriggerUsed(newEventString)) {
+            if (mouseInputButton.eventString === newEventString) {
+                // fire changed signal so deleted button can return if needed
+                mouseInputButton.eventStringChanged()
+            } else {
+                mouseInputButton.eventString = newEventString;
+            }
+            mouseInputButton.checked = false;
+        } else {
+            mouseInputButton.usedTrigger = newEventString;
+        }
+    }
+
     MouseArea {
         id: mouseInputArea
         anchors.fill: parent
         acceptedButtons: Qt.AllButtons
-        enabled: false
+        enabled: mouseInputButton.checked

         onClicked: mouse => {
-            var newEventString = configDialog.currentContainmentActionsModel.mouseEventString(mouse.button, mouse.modifiers);
-
-            if (mouseInputButton.eventString === newEventString || !configDialog.currentContainmentActionsModel.isTriggerUsed(newEventString)) {
-                if (mouseInputButton.eventString === newEventString) {
-                    // fire changed signal so deleted button can return if needed
-                    mouseInputButton.eventStringChanged()
-                } else {
-                    mouseInputButton.eventString = newEventString;
-                }
-                mouseInputButton.text = mouseInputButton.defaultText;
-                mouseInputButton.checked = false;
-                enabled = false;
-            }
+            mouseInputButton.setEventString(configDialog.currentContainmentActionsModel.mouseEventString(mouse.button, mouse.modifiers));
         }

         onWheel: wheel => {
-            var newEventString = configDialog.currentContainmentActionsModel.wheelEventString(wheel);
-
-            if (mouseInputButton.eventString === newEventString || !configDialog.currentContainmentActionsModel.isTriggerUsed(newEventString)) {
-                mouseInputButton.eventString = newEventString;
-                mouseInputButton.text = mouseInputButton.defaultText;
-                mouseInputButton.checked = false;
-                enabled = false;
-            }
+            mouseInputButton.setEventString(configDialog.currentContainmentActionsModel.wheelEventString(wheel));
         }
     }
 }
-- 
